"""P3 — Impact sur la Satisfaction"""import streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, to_rgbafrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_satisfactiondef render():    page_header("Impact sur la Satisfaction",                "Écarts selon le type de flux · critères livraison, description, communication",                "⭐")    data = load_satisfaction()    df_type    = data["par_type"]    df_domintl = data["dom_intl"]    df_top     = data["top_sellers"]    kpi_row([        {"title": "Satisfaction domestique", "value": "4.839 / 5",         "subtitle": "Référence marché", "color": "green", "icon": "🏠"},        {"title": "Satisfaction internationale", "value": "4.814 / 5",         "subtitle": "–0.025 vs domestique", "color": "blue", "icon": "✈️"},        {"title": "Intra-EU", "value": "4.809 / 5",         "subtitle": "Note la plus basse", "color": "orange", "icon": "🇪🇺"},        {"title": "Intercontinental", "value": "4.821 / 5",         "subtitle": "Mieux qu'intra-EU ✓", "color": "teal", "icon": "🌏"},    ])    section_title("Comparaison multi-critères par type de flux", "📊")    criteria = ["Note Globale", "Livraison", "Description", "Communication"]    colors_type = {        "Domestique":       C["green"],        "Intercontinental": C["teal"],        "Intra-EU":         C["orange"],    }    fig = go.Figure()    for _, row in df_type.iterrows():        t = row["Type"]        fig.add_trace(go.Bar(            name=t,            x=criteria,            y=[row[c] for c in criteria],            marker=dict(                color=colors_type.get(t, C["blue"]),                opacity=0.85,                line=dict(color=C["bg"], width=0.8)            ),            text=[f"{row[c]:.3f}" for c in criteria],            textposition="outside",            textfont=dict(size=11),            hovertemplate=f"<b>{t}</b><br>%{{x}} : <b>%{{y:.3f}}</b><extra></extra>",        ))    apply_theme(fig, "Note moyenne par critère et par type de transaction")    fig.update_layout(        barmode="group", height=380,        yaxis=dict(range=[4.77, 4.86]),        legend=dict(orientation="h", x=0.5, xanchor="center", y=1.05)    )    st.plotly_chart(fig, use_container_width=True)    col1, col2 = st.columns(2)    with col1:        section_title("Radar : Domestique vs International", "🕸️")        cats = ["Note Globale", "Livraison", "Description", "Communication"]        fig_r = go.Figure()        for _, row in df_domintl.iterrows():            t = row["Type"]            vals_norm = [(row[c] - 4.70) / (5.00 - 4.70) for c in cats]            color = C["green"] if "Dom" in t else C["blue"]            fig_r.add_trace(go.Scatterpolar(                r=vals_norm + [vals_norm[0]],                theta=cats + [cats[0]],                fill="toself",                name=t,                line=dict(color=color, width=2),                fillcolor=to_rgba(color, 0.2),                hovertemplate="%{theta}: <b>%{r:.0%}</b> du max<extra></extra>",            ))        apply_theme(fig_r, "")        fig_r.update_layout(            polar=dict(                bgcolor=C["card"],                radialaxis=dict(                    visible=True, range=[0, 1],                    showticklabels=False, gridcolor=C["grid"]                ),                angularaxis=dict(                    gridcolor=C["border"],                    tickfont=dict(color=C["muted"])                )            ),            showlegend=True, height=340        )        st.plotly_chart(fig_r, use_container_width=True)    with col2:        section_title("Top 10 pays vendeurs — lollipop", "🏆")        df_s = df_top.sort_values("Note Globale", ascending=True)        ref  = 4.821        fig_l = go.Figure()        fig_l.add_vline(            x=ref, line_dash="dash", line_color=C["border"],            annotation_text=f"Moy. marché {ref}",            annotation_position="top right",            annotation_font_color=C["muted"]        )        for _, row in df_s.iterrows():            fig_l.add_shape(                type="line",                x0=ref, x1=row["Note Globale"],                y0=row["Pays vendeur"], y1=row["Pays vendeur"],                line=dict(                    color=C["green"] if row["Note Globale"] >= ref else C["orange"],                    width=2                )            )        fig_l.add_trace(go.Scatter(            x=df_s["Note Globale"],            y=df_s["Pays vendeur"],            mode="markers+text",            marker=dict(                size=12,                line=dict(color=C["bg"], width=2),                color=[C["green"] if v >= ref else C["orange"]                       for v in df_s["Note Globale"]]            ),            text=[f" {v:.3f}" for v in df_s["Note Globale"]],            textposition="middle right",            textfont=dict(color=C["text"], size=11),            hovertemplate="<b>%{y}</b><br>%{x:.3f} / 5<extra></extra>",        ))        apply_theme(fig_l, "")        fig_l.update_layout(            height=340,            xaxis=dict(range=[4.82, 4.92]),            margin=dict(l=10, r=60, t=20, b=20),            showlegend=False        )        st.plotly_chart(fig_l, use_container_width=True)